  const tagged = stayLink(
    { checkinISO: "2026-10-18", label: "edfringenow-jerusalem-night" },
    { ...AFFILIATES, bookingAid: "7654321" }
  );
  assert.equal(query(tagged.url).get("label"), "edfringenow-jerusalem-night");
});

