cd /home/user/EdFringeNow/product/requirements/shared/harness/vendor/fonts && curl -sS --max-time 40 -o heebo_v28_NGS6v5_NC0k9P9H0TbFzsQ.woff2 "https://fonts.gstatic.com/s/heebo/v28/NGS6v5_NC0k9P9H0TbFzsQ.woff2" && curl -sS --max-time 40 -o heebo_v28_NGS6v5_NC0k9P9H2TbE.woff2 "https://fonts.gstatic.com/s/heebo/v28/NGS6v5_NC0k9P9H2TbE.woff2" && ls -l heebo* && python3 - <<'PY'
hebrew = "U+0307-0308, U+0590-05FF, U+200C-2010, U+20AA, U+25CC, U+FB1D-FB4F"
latin = "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD"
blocks = ["""
/* Heebo — the Hebrew face the festival planner loads. Google serves it as one
   variable file per subset, so every weight below points at the same two files;
   only the hebrew and latin subsets are vendored, which is all the product's
   Hebrew and its Latin fallback need. */"""]
for weight in (400, 600, 700, 800):
    for name, rng, f in (("hebrew", hebrew, "heebo_v28_NGS6v5_NC0k9P9H0TbFzsQ.woff2"),
                         ("latin", latin, "heebo_v28_NGS6v5_NC0k9P9H2TbE.woff2")):
        blocks.append(f"""/* {name} */
@font-face {{
  font-family: 'Heebo';
  font-style: normal;
  font-weight: {weight};
  font-display: swap;
  src: url(/__vendor/fonts/{f}) format('woff2');
  unicode-range: {rng};
}}""")
with open("fonts.css", "a", encoding="utf-8") as h:
    h.write("\n".join(blocks) + "\n")
PY
grep -c "Heebo" fonts.css

