  venueLat: 31.779724,
  venueLng: 35.212583,
  url: "https://comedy-festival.co.il/events/salakh/",
};

// "קריוקי רייב" publishes no running time. Four of the festival's shows don't.
const UNTIMED = {
  ...TIMED,
  slug: "karaoke-rave",
  title: "קריוקי רייב",
  date: "2026-10-21",
  realDate: "2026-10-21",
  startTime: "22:00",
  start: at("2026-10-21", "22:00"),
  end: at("2026-10-21", "22:00"),
  duration: null,
};

